import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testMultipleOccurrences() {
        Assert.assertEquals(2, countOccurrences(listOf("red", "blue", "red"), "red"))
    }

    @Test
    fun testNoOccurrences() {
        Assert.assertEquals(0, countOccurrences(listOf("red", "blue", "red"), "green"))
    }

    @Test
    fun testAllSame() {
        Assert.assertEquals(3, countOccurrences(listOf("blue", "blue", "blue"), "blue"))
    }

    @Test
    fun testEmptyList() {
        Assert.assertEquals(0, countOccurrences(emptyList(), "red"))
    }
}
